def count_isolated(grid, color):
    rows = len(grid)
    cols = len(grid[0])
    count = 0
    visited = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r,c) not in visited:
                # BFS to find component
                component = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) not in visited and grid[cr][cc] == color:
                        visited.add((cr, cc))
                        component.append((cr, cc))
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color:
                                stack.append((nr, nc))
                if len(component) == 1:
                    count += 1
    return count

